  SIGNAL ddsm_11                          : std_logic;  -- ufix1
  SIGNAL ddsm_12                          : std_logic;  -- ufix1
  SIGNAL ddsm_13                          : std_logic;  -- ufix1
  SIGNAL ddsm_14                          : std_logic;  -- ufix1
