  SIGNAL ddsm_15                          : std_logic;  -- ufix1
  SIGNAL ddsm_16                          : std_logic;  -- ufix1
  SIGNAL ddsm_17                          : std_logic;  -- ufix1
  SIGNAL ddsm_18                          : std_logic;  -- ufix1
  SIGNAL ddsm_19                          : std_logic;  -- ufix1
  SIGNAL ddsm_20                          : std_logic;  -- ufix1
  SIGNAL ddsm_21                          : std_logic;  -- ufix1
  SIGNAL dLUT4                            : unsigned(6 DOWNTO 0);  -- ufix7
  SIGNAL ddsm_22                          : std_logic;  -- ufix1
  SIGNAL ddsm_23                          : std_logic;  -- ufix1
  SIGNAL ddsm_24                          : std_logic;  -- ufix1
  SIGNAL ddsm_25                          : std_logic;  -- ufix1
  SIGNAL ddsm_26                          : std_logic;  -- ufix1
  SIGNAL ddsm_27                          : std_logic;  -- ufix1
  SIGNAL ddsm_28                          : std_logic;  -- ufix1
