  c_Shift1_12 <= cLUT3(43 DOWNTO 33);

  cLUT4 <= LUT4_table_data(to_integer(vAddr1));

  c_Shift1_13 <= cLUT4(10 DOWNTO 0);

  c_Shift1_14 <= cLUT4(21 DOWNTO 11);

  c_Shift1_15 <= cLUT4(32 DOWNTO 22);

  c_Shift1_16 <= cLUT4(43 DOWNTO 33);

  cLUT5 <= LUT5_table_data(to_integer(vAddr1));

  c_Shift1_17 <= cLUT5(10 DOWNTO 0);

  c_Shift1_18 <= cLUT5(21 DOWNTO 11);

  c_Shift1_19 <= cLUT5(32 DOWNTO 22);

  c_Shift1_20 <= cLUT5(43 DOWNTO 33);

  cLUT6 <= LUT6_table_data(to_integer(vAddr1));

  c_Shift1_21 <= cLUT6(10 DOWNTO 0);

  c_Shift1_22 <= cLUT6(21 DOWNTO 11);

  c_Shift1_23 <= cLUT6(32 DOWNTO 22);

  c_Shift1_24 <= cLUT6(43 DOWNTO 33);

  cLUT7 <= LUT7_table_data(to_integer(vAddr1));

  c_Shift1_25 <= cLUT7(10 DOWNTO 0);

  c_Shift1_26 <= cLUT7(21 DOWNTO 11);

  c_Shift1_27 <= cLUT7(32 DOWNTO 22);

  c_Shift1_28 <= cLUT7(43 DOWNTO 33);

  
  cShiftD <= c_Shift1_1 WHEN iCountTmp = to_unsigned(16#00#, 5) ELSE
      c_Shift1_1 WHEN iCountTmp = to_unsigned(16#01#, 5) ELSE
