      c_Shift1_3 WHEN iCountTmp = to_unsigned(16#03#, 5) ELSE
      c_Shift1_4 WHEN iCountTmp = to_unsigned(16#04#, 5) ELSE
      c_Shift1_5 WHEN iCountTmp = to_unsigned(16#05#, 5) ELSE
