  ddsm_10 <= dLUT2(2);

  ddsm_11 <= dLUT2(3);

  ddsm_12 <= dLUT2(4);

  ddsm_13 <= dLUT2(5);

  ddsm_14 <= dLUT2(6);

  dLUT3 <= LUT3_table_data_4(to_integer(vAddr1));

  ddsm_15 <= dLUT3(0);

  ddsm_16 <= dLUT3(1);

  ddsm_17 <= dLUT3(2);

  ddsm_18 <= dLUT3(3);

  ddsm_19 <= dLUT3(4);

  ddsm_20 <= dLUT3(5);

  ddsm_21 <= dLUT3(6);

  dLUT4 <= LUT4_table_data_4(to_integer(vAddr1));

  ddsm_22 <= dLUT4(0);

  ddsm_23 <= dLUT4(1);

  ddsm_24 <= dLUT4(2);

  ddsm_25 <= dLUT4(3);

  ddsm_26 <= dLUT4(4);

  ddsm_27 <= dLUT4(5);

  ddsm_28 <= dLUT4(6);

  
  ddsmD <= ddsm_1 WHEN iCountTmp = to_unsigned(16#00#, 5) ELSE
      ddsm_1 WHEN iCountTmp = to_unsigned(16#01#, 5) ELSE
      ddsm_2 WHEN iCountTmp = to_unsigned(16#02#, 5) ELSE
      ddsm_3 WHEN iCountTmp = to_unsigned(16#03#, 5) ELSE
      ddsm_4 WHEN iCountTmp = to_unsigned(16#04#, 5) ELSE
      ddsm_5 WHEN iCountTmp = to_unsigned(16#05#, 5) ELSE
      ddsm_6 WHEN iCountTmp = to_unsigned(16#06#, 5) ELSE
      ddsm_7 WHEN iCountTmp = to_unsigned(16#07#, 5) ELSE
      ddsm_8 WHEN iCountTmp = to_unsigned(16#08#, 5) ELSE
      ddsm_9 WHEN iCountTmp = to_unsigned(16#09#, 5) ELSE
      ddsm_10 WHEN iCountTmp = to_unsigned(16#0A#, 5) ELSE
      ddsm_11 WHEN iCountTmp = to_unsigned(16#0B#, 5) ELSE
      ddsm_12 WHEN iCountTmp = to_unsigned(16#0C#, 5) ELSE
      ddsm_13 WHEN iCountTmp = to_unsigned(16#0D#, 5) ELSE
      ddsm_14 WHEN iCountTmp = to_unsigned(16#0E#, 5) ELSE
      ddsm_15 WHEN iCountTmp = to_unsigned(16#0F#, 5) ELSE
      ddsm_16 WHEN iCountTmp = to_unsigned(16#10#, 5) ELSE
      ddsm_17 WHEN iCountTmp = to_unsigned(16#11#, 5) ELSE
