      ddsm_25 WHEN iCountTmp = to_unsigned(16#19#, 5) ELSE
      ddsm_26 WHEN iCountTmp = to_unsigned(16#1A#, 5) ELSE
      ddsm_27 WHEN iCountTmp = to_unsigned(16#1B#, 5) ELSE
      ddsm_28;

  alpha0_4_process : PROCESS (clk)
  BEGIN
    IF clk'EVENT AND clk = '1' THEN
      IF reset = '1' THEN
        ddsm <= '0';
      ELSIF enb = '1' THEN
        ddsm <= ddsmD;
      END IF;
    END IF;
  END PROCESS alpha0_4_process;


END rtl;

